package com.benhsoan.domain.medicalrecord;
import static org.junit.jupiter.api.Assertions.*; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import com.benhsoan.domain.medicalrecord.enums.MedicalRecordAccessAction; import com.benhsoan.domain.shared.exception.ValidationException;
class MedicalRecordAccessLogTest { @Test void createsHistoryViewWithoutRecordIds(){var log=MedicalRecordAccessLog.createHistoryView(UUID.randomUUID(),UUID.randomUUID(),null,null,Instant.parse("2026-08-20T02:00:00Z"));assertEquals(MedicalRecordAccessAction.VIEW_HISTORY,log.getAction());assertNull(log.getVisitId());} @Test void rejectsRecordAccessWithoutRecord(){assertThrows(ValidationException.class,()->MedicalRecordAccessLog.createRecordAccess(UUID.randomUUID(),null,null,UUID.randomUUID(),MedicalRecordAccessAction.VIEW,null,null));}}
